"""Regression tests for chart-bump-classify.py, the rule that lets a bot bump merge alone.

A false "routine" merges and releases a chart nobody reviewed, so every case that must
reach a human is pinned here, next to the shapes the push bot really produces.

    python3 -m unittest discover -s .github/scripts -p 'test_*.py'
"""

import importlib.util
import os
import unittest

_spec = importlib.util.spec_from_file_location(
    "chart_bump_classify", os.path.join(os.path.dirname(os.path.abspath(__file__)), "chart-bump-classify.py")
)
cbc = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(cbc)

BODY = """## Summary

Automated update of Helm chart components.

## Components Updated

| Component | Version | New Env Vars |
|-----------|---------|--------------|
| product-console | 3.5.0 | - |

---
*This PR was automatically generated by the CI/CD pipeline.*
"""

CHART_BASE = """apiVersion: v2
name: product-console
description: A Helm chart for Product Console - Lerian Studio's web interface
  for managing Midaz ledger
version: 4.5.4
appVersion: "3.4.0"
"""
CHART_HEAD = """apiVersion: v2
name: product-console
description: A Helm chart for Product Console - Lerian Studio's web interface for managing Midaz ledger
version: 4.5.4
appVersion: "3.5.0"
"""
VALUES_BASE = """image:
  repository: lerianstudio/product-console
  tag: "3.4.0"
replicaCount: 1
"""
VALUES_HEAD = VALUES_BASE.replace('"3.4.0"', '"3.5.0"')

CHART = "charts/product-console/Chart.yaml"
VALUES = "charts/product-console/values.yaml"


def commit(**kw):
    return {"sha": "abcdef1234", "author": "lerian-studio", "committer": "lerian-studio", "verified": True, **kw}


class Classify(unittest.TestCase):
    def run_case(self, pr=None, files=None, commits=None, chart=(CHART_BASE, CHART_HEAD), values=(VALUES_BASE, VALUES_HEAD)):
        pr = {"base": "main", "title": "fix(product-console): update product-console@3.5.0", "body": BODY, **(pr or {})}
        files = files if files is not None else [
            {"filename": CHART, "status": "modified"},
            {"filename": VALUES, "status": "modified"},
        ]
        contents = {
            (CHART, "base"): chart[0], (CHART, "head"): chart[1],
            (VALUES, "base"): values[0], (VALUES, "head"): values[1],
        }
        return cbc.classify(pr, files, commits if commits is not None else [commit()], contents)

    def assertRoutine(self, result):
        self.assertTrue(result[0], result[1])

    def assertManual(self, result, fragment):
        self.assertFalse(result[0], result[1])
        self.assertIn(fragment, result[1])

    # The shape of #3207: appVersion + image.tag + a reflowed description.
    def test_minor_bump_with_description_is_routine(self):
        result = self.run_case()
        self.assertRoutine(result)
        self.assertEqual(result[2], "product-console")

    def test_patch_bump_of_nested_component_tags_is_routine(self):
        base = "ledger:\n  image:\n    tag: 4.4.1\ncrm:\n  image:\n    tag: 3.8.9\n"
        head = "ledger:\n  image:\n    tag: 4.4.2\ncrm:\n  image:\n    tag: 3.8.9\n"
        self.assertRoutine(self.run_case(values=(base, head)))

    def test_values_only_bump_is_routine(self):
        self.assertRoutine(self.run_case(files=[{"filename": VALUES, "status": "modified"}]))

    def test_downgrade_is_manual(self):
        self.assertManual(self.run_case(values=(VALUES_HEAD, VALUES_BASE), chart=(CHART_HEAD, CHART_BASE)), "not an upgrade")

    def test_major_bump_is_manual(self):
        self.assertManual(self.run_case(values=(VALUES_BASE, VALUES_BASE.replace('"3.4.0"', '"4.0.0"'))), "major")

    def test_prerelease_is_manual(self):
        self.assertManual(self.run_case(values=(VALUES_BASE, VALUES_BASE.replace('"3.4.0"', '"3.5.0-beta.1"'))), "X.Y.Z")

    def test_no_version_change_is_manual(self):
        self.assertManual(self.run_case(chart=(CHART_BASE, CHART_BASE), values=(VALUES_BASE, VALUES_BASE)), "no version")

    def test_other_values_change_is_manual(self):
        head = VALUES_HEAD.replace("replicaCount: 1", "replicaCount: 2")
        self.assertManual(self.run_case(values=(VALUES_BASE, head)), "replicaCount")

    def test_new_values_key_is_manual(self):
        self.assertManual(self.run_case(values=(VALUES_BASE, VALUES_HEAD + "extraEnv:\n  FOO: bar\n")), "adds or removes")

    def test_image_repository_change_is_manual(self):
        head = VALUES_HEAD.replace("lerianstudio/product-console", "evil/product-console")
        self.assertManual(self.run_case(values=(VALUES_BASE, head)), "image.repository")

    def test_chart_version_change_is_manual(self):
        self.assertManual(self.run_case(chart=(CHART_BASE, CHART_HEAD.replace("4.5.4", "4.5.5"))), "version")

    def test_template_change_is_manual(self):
        files = [{"filename": "charts/product-console/templates/configmap.yaml", "status": "modified"}]
        self.assertManual(self.run_case(files=files), "outside")

    def test_docs_alongside_is_manual(self):
        files = [{"filename": VALUES, "status": "modified"}, {"filename": "charts/product-console/docs/UPGRADE-3.0.md", "status": "added"}]
        self.assertManual(self.run_case(files=files), "outside")

    def test_feat_title_is_manual(self):
        self.assertManual(self.run_case(pr={"title": "feat(product-console): update product-console@3.5.0"}), "feat(")

    def test_env_vars_in_table_is_manual(self):
        body = BODY.replace("| product-console | 3.5.0 | - |", "| product-console | 3.5.0 | FOO_URL |")
        self.assertManual(self.run_case(pr={"body": body}), "FOO_URL")

    def test_legacy_is_manual(self):
        self.assertManual(self.run_case(pr={"base": "maintenance/product-console-3.4.x"}), "base branch")
        self.assertManual(self.run_case(pr={"title": "fix(x): update x@1.2.3 [legacy 1.2.x]"}), "legacy")

    def test_foreign_commit_is_manual(self):
        self.assertManual(self.run_case(commits=[commit(), commit(author="someone", committer="someone")]), "someone")

    def test_unsigned_commit_is_manual(self):
        self.assertManual(self.run_case(commits=[commit(verified=False)]), "verified")

    def test_two_charts_is_manual(self):
        files = [{"filename": VALUES, "status": "modified"}, {"filename": "charts/midaz/values.yaml", "status": "modified"}]
        self.assertManual(self.run_case(files=files), "several charts")


if __name__ == "__main__":
    unittest.main()
